// Pre-defined palette of highly distinct hues (spread out across 360 degrees)
const DISTINCT_HUES = [
    0,   // Red
    30,  // Orange
    60,  // Yellow/Gold
    90,  // Lime Green
    130, // Green
    170, // Teal
    200, // Light Blue
    230, // Blue
    270, // Purple
    300, // Magenta
    330, // Pink
];

export const stringToColor = (str) => {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
        hash = str.charCodeAt(i) + ((hash << 5) - hash);
    }

    // Map the hash to one of our strictly distinct hues
    const index = Math.abs(hash) % DISTINCT_HUES.length;
    const hue = DISTINCT_HUES[index];

    // Adjusted for brighter, more distinct colors
    return `hsl(${hue}, 85%, 65%)`;
};

export const stringToDarkColor = (str) => {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
        hash = str.charCodeAt(i) + ((hash << 5) - hash);
    }
    const index = Math.abs(hash) % DISTINCT_HUES.length;
    const hue = DISTINCT_HUES[index];
    return `hsl(${hue}, 70%, 30%)`;
};
