import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { useAppState } from "../../app/providers";
import { selectQueueState } from "../../state/selectors";
import config from "../../config";
import { DEFAULT_MASTER_PASSWORD } from "../../common/utils/settingsDefaults";

export default function LandingPage() {
    const navigate = useNavigate();
    const { setUserRole, setStaffName, settings } = useAppState(selectQueueState);

    const [isAdminPromptOpen, setIsAdminPromptOpen] = useState(false);
    const [isStaffPromptOpen, setIsStaffPromptOpen] = useState(false);
    const [staffNameInput, setStaffNameInput] = useState("");
    const [staffError, setStaffError] = useState("");
    const [password, setPassword] = useState("");
    const [error, setError] = useState("");

    const handleStaffLogin = () => {
        const name = staffNameInput.trim();
        if (!name) {
            setStaffError("Please enter your name.");
            return;
        }
        setStaffName(name);
        setUserRole("staff");
        setIsStaffPromptOpen(false);
        setStaffError("");
        navigate("/calendar-v2");
    };

    const handleAdminLogin = () => {
        if (password === (settings?.masterPassword || DEFAULT_MASTER_PASSWORD)) {
            setUserRole("admin");
            navigate("/dashboard");
        } else {
            setError("Incorrect password");
        }
    };

    return (
        <div className="min-h-screen w-full bg-pt-canvas flex items-center justify-center p-4 font-body text-pt-navy">
            <div className="w-full max-w-2xl bg-white rounded-3xl shadow-2xl border border-pt-slate-500/10 overflow-hidden flex flex-col md:flex-row">

                {/* Left Side: Branding */}
                <div className="bg-pt-navy text-white p-10 flex flex-col justify-center items-center md:w-5/12 text-center">
                    <div className="w-28 h-28 bg-white rounded-full flex items-center justify-center mb-6 shadow-lg overflow-hidden border-4 border-pt-orange">
                        <img src={config.assetPath("logo.png")} alt={config.name} className="w-full h-full object-cover" />
                    </div>
                    <h1 className="text-5xl font-signature mb-2 text-pt-orange">{config.name}</h1>
                    <p className="opacity-80 text-sm">{config.tagline || "Pickleball Facility"}</p>
                </div>

                {/* Right Side: Selection */}
                <div className="p-10 md:w-7/12 flex flex-col justify-center">

                    {!isAdminPromptOpen && !isStaffPromptOpen ? (
                        <>
                            <h2 className="text-2xl font-bold mb-8 text-center uppercase tracking-wide">Select User Role</h2>
                            <div className="space-y-4">
                                <button
                                    type="button"
                                    onClick={() => {
                                        setStaffNameInput("");
                                        setStaffError("");
                                        setIsStaffPromptOpen(true);
                                    }}
                                    className="w-full group relative p-6 border-2 border-pt-slate-500/10 rounded-2xl hover:border-pt-orange hover:bg-pt-orange/5 transition-all text-left"
                                >
                                    <div className="flex items-center gap-4">
                                        <span className="text-3xl p-3 bg-pt-orange/10 rounded-full group-hover:bg-pt-orange group-hover:text-white transition-colors">👋</span>
                                        <div>
                                            <h3 className="text-lg font-bold text-pt-navy">Staff</h3>
                                            <p className="text-xs text-slate-500">Operations, Queue, Calendar</p>
                                        </div>
                                    </div>
                                </button>

                                <button
                                    type="button"
                                    onClick={() => setIsAdminPromptOpen(true)}
                                    className="w-full group relative p-6 border-2 border-pt-slate-500/10 rounded-2xl hover:border-pt-green hover:bg-pt-green/5 transition-all text-left"
                                >
                                    <div className="flex items-center gap-4">
                                        <span className="text-3xl p-3 bg-pt-green/10 text-pt-green-dark rounded-full group-hover:bg-pt-green group-hover:text-white transition-colors">🔒</span>
                                        <div>
                                            <h3 className="text-lg font-bold text-pt-navy">Admin / Owner</h3>
                                            <p className="text-xs text-slate-500">Full Access to All Modules</p>
                                        </div>
                                    </div>
                                </button>
                            </div>
                        </>
                    ) : isStaffPromptOpen ? (
                        <div className="animate-in slide-in-from-right fade-in duration-300">
                            <button
                                type="button"
                                onClick={() => {
                                    setIsStaffPromptOpen(false);
                                    setStaffError("");
                                    setStaffNameInput("");
                                }}
                                className="text-xs font-bold text-slate-400 hover:text-pt-navy mb-6 flex items-center gap-1"
                            >
                                ← BACK
                            </button>
                            <h2 className="text-xl font-bold mb-2">Staff sign-in</h2>
                            <p className="text-xs text-slate-500 mb-6">Your name is recorded on session and booking history.</p>

                            <form onSubmit={(e) => { e.preventDefault(); handleStaffLogin(); }}>
                                <input
                                    type="text"
                                    autoFocus
                                    className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl focus:border-pt-orange focus:ring-pt-orange outline-none transition-all mb-2 text-lg"
                                    placeholder="Your name"
                                    value={staffNameInput}
                                    onChange={(e) => {
                                        setStaffNameInput(e.target.value);
                                        setStaffError("");
                                    }}
                                />
                                {staffError && <p className="text-red-500 text-xs font-bold mb-4">{staffError}</p>}

                                <button
                                    type="submit"
                                    className="w-full bg-pt-orange text-white py-4 rounded-xl font-bold hover:bg-pt-orange-dark transition-transform active:scale-95 shadow-lg mt-2"
                                >
                                    Continue to Calendar
                                </button>
                            </form>
                        </div>
                    ) : (
                        <div className="animate-in slide-in-from-right fade-in duration-300">
                            <button
                                type="button"
                                onClick={() => {
                                    setIsAdminPromptOpen(false);
                                    setError("");
                                    setPassword("");
                                }}
                                className="text-xs font-bold text-slate-400 hover:text-pt-navy mb-6 flex items-center gap-1"
                            >
                                ← BACK
                            </button>
                            <h2 className="text-xl font-bold mb-2">Admin Access</h2>
                            <p className="text-xs text-slate-500 mb-6">Enter the master password to continue.</p>

                            <form onSubmit={(e) => { e.preventDefault(); handleAdminLogin(); }}>
                                <input
                                    type="password"
                                    autoFocus
                                    className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl focus:border-pt-orange focus:ring-pt-orange outline-none transition-all mb-4 font-mono text-lg"
                                    placeholder="Password"
                                    value={password}
                                    onChange={(e) => setPassword(e.target.value)}
                                />
                                {error && <p className="text-red-500 text-xs font-bold mb-4">{error}</p>}

                                <button
                                    type="submit"
                                    className="w-full bg-pt-orange text-white py-4 rounded-xl font-bold hover:bg-pt-orange-dark transition-transform active:scale-95 shadow-lg"
                                >
                                    Unlock Dashboard
                                </button>
                            </form>
                        </div>
                    )}

                </div>
            </div>

            <div className="absolute bottom-4 text-center w-full text-pt-navy/20 text-[10px] font-mono pointer-events-none">
                POWERED BY DINK MANAGER
            </div>
        </div>
    );
}
