/** Format hour (0–23) as compact AM/PM label, e.g. "8 AM", "2 PM". */
export function formatHourAmpm(hour) {
  const d = new Date();
  d.setHours(hour, 0, 0, 0);
  return d.toLocaleTimeString([], { hour: "numeric", hour12: true });
}

/** Format minutes from midnight as "2:00 PM". */
export function formatMinutesAmpm(totalMinutes) {
  if (totalMinutes == null || !Number.isFinite(Number(totalMinutes))) return "??:??";
  const mins = Number(totalMinutes);
  const h = Math.floor(mins / 60);
  const m = mins % 60;
  const d = new Date();
  d.setHours(h, m, 0, 0);
  return d.toLocaleTimeString([], { hour: "numeric", minute: "2-digit", hour12: true });
}

/** Format a slot start–end range in AM/PM. */
export function formatSlotTimeRange(startTime, endTime) {
  return `${formatMinutesAmpm(startTime)} - ${formatMinutesAmpm(endTime)}`;
}

/** Resolve cell status for a court/hour on a given date. */
export function resolveHourStatus({
  slots = [],
  bookings = {},
  courtId,
  dateYmd,
  hour,
}) {
  const timeInMinutes = hour * 60;
  const activeSlot = slots.find((s) => {
    if (String(s.courtId) !== String(courtId)) return false;
    if (s.date !== dateYmd || s.status !== "ACTIVE") return false;
    const b = bookings[s.bookingId];
    if (b && b.status === "CANCELLED") return false;
    return timeInMinutes >= s.startTime && timeInMinutes < s.endTime;
  });

  if (!activeSlot) return { kind: "available" };

  const booking = bookings[activeSlot.bookingId];
  if (!booking) return { kind: "available" };

  if (booking.type === "OPEN_PLAY_BLOCK") {
    return { kind: "unavailable", booking };
  }

  return { kind: "booked", booking };
}

export const POST_STATUS = {
  available: { label: "Available", short: "Open" },
  booked: { label: "Booked", short: "Booked" },
  unavailable: { label: "Unavailable", short: "N/A" },
};
