import { CURRENT_STATE_VERSION, normalizeStateMeta, withStateEnvelope } from "./schema";

// A helper to save/load from localStorage with basic versioning metadata
// Storage key is client-specific so each client deployment has isolated state

export const APP_STORAGE_KEY = "chillClubAppState";

const getStorageKey = () => {
  // Pickle & Chill uses a dedicated state key isolated from other clients.
  return APP_STORAGE_KEY;
};

const getStorage = () => {
  if (typeof window !== "undefined" && window.localStorage) {
    return window.localStorage;
  }
  return null;
};

const CALENDAR_PERSIST_KEYS = ["bookings", "calendarCourts", "bookingsV2", "slotsV2"];

export function saveState(state = {}) {
  try {
    const storage = getStorage();
    if (!storage) {
      console.warn("Local storage unavailable; skipping saveState.");
      return null;
    }
    const sanitized = { ...state };
    CALENDAR_PERSIST_KEYS.forEach((key) => {
      delete sanitized[key];
    });
    delete sanitized.isDemoMode;

    const payload = withStateEnvelope(sanitized);
    storage.setItem(getStorageKey(), JSON.stringify(payload));
    return payload;
  } catch (err) {
    console.error("Failed to save state", err);
    return null;
  }
}

export function loadState() {
  try {
    const storage = getStorage();
    if (!storage) return null;

    const key = getStorageKey();
    const saved = storage.getItem(key);

    const raw = saved;
    if (!raw) return null;

    const parsed = JSON.parse(raw);

    const legacyMeta = parsed.meta || {};
    const normalizedMeta = normalizeStateMeta({
      ...legacyMeta,
      seededAt: legacyMeta.seededAt || parsed.seededAt || null,
      seedSource: legacyMeta.seedSource || parsed.seedSource || null,
      seedLabel: legacyMeta.seedLabel || parsed.seedLabel || null,
      lastSavedAt:
        legacyMeta.lastSavedAt ||
        legacyMeta.savedAt ||
        parsed.lastSavedAt ||
        parsed.savedAt ||
        null,
      stateVersion: legacyMeta.stateVersion || parsed.version || CURRENT_STATE_VERSION,
    });

    // STRICT ONLINE MODE: Remove Calendar Data from Local Persistence
    const sanitized = { ...parsed };
    CALENDAR_PERSIST_KEYS.forEach((key) => {
      delete sanitized[key];
    });
    delete sanitized.isDemoMode;

    return {
      ...sanitized,
      meta: normalizedMeta,
      version: parsed.version || CURRENT_STATE_VERSION,
    };
  } catch (err) {
    console.error("Failed to load state", err);
    return null;
  }
}
