import React from "react";

/** Small letter chip for teams mode — hidden when teamsModeEnabled is false */
export default function TeamBadge({
  letter = "?",
  color = "#64748B",
  title,
  className = "",
}) {
  const initial = String(letter || "?").charAt(0).toUpperCase();
  return (
    <span
      title={title || ""}
      className={`inline-flex items-center justify-center min-w-[1.25rem] h-5 px-1 rounded text-[10px] font-bold text-white shadow-sm shrink-0 ${className}`}
      style={{ backgroundColor: color }}
    >
      {initial}
    </span>
  );
}

export function resolvePlayerTeamBadge(player, teams = [], teamsModeEnabled, unassignedLabel = "Unassigned") {
  if (!teamsModeEnabled) return null;
  if (!player?.teamId) {
    return { letter: "U", color: "#64748B", title: unassignedLabel };
  }
  const t = teams.find((x) => String(x.id) === String(player.teamId));
  if (!t) return { letter: "?", color: "#94A3B8", title: "Team" };
  return {
    letter: t.letter || t.name?.charAt(0) || "?",
    color: t.color || "#3B82F6",
    title: t.name,
  };
}

/** Prefer structured teamMeta sides (queue/court snapshots); fall back to roster teamId. */
export function resolveTeamBadgeDisplay(
  player,
  teamMeta,
  teamsModeEnabled,
  teams = [],
  unassignedLabel = "Unassigned"
) {
  if (!teamsModeEnabled) return null;
  if (teamMeta?.sideA?.players?.length && teamMeta?.sideB?.players?.length) {
    const pid = String(player.id);
    const idsA = teamMeta.sideA.players.map(String);
    const idsB = teamMeta.sideB.players.map(String);
    const side = idsA.includes(pid) ? teamMeta.sideA : idsB.includes(pid) ? teamMeta.sideB : null;
    if (side) {
      return {
        letter: side.letter ?? side.name?.charAt(0)?.toUpperCase() ?? "?",
        color: side.color ?? "#64748B",
        title: side.name ?? "",
      };
    }
  }
  return resolvePlayerTeamBadge(player, teams, true, unassignedLabel);
}
