import React, { useMemo, useState } from "react";
import { useAppState } from "../../app/providers";
import { selectHistoryState } from "../../state/selectors";
import { SurfaceCard, ConfirmationModal } from "../../common/components";
import SettlePaymentModal from "../dashboard/components/SettlePaymentModal";
import {
  classifyPlayerPaymentBucket,
  isPlayerPaid,
  isPlayerPaidWithCharge,
  isPlayerUnpaid,
  isPlayerFree,
  normalizePaymentMethod,
  PAID_PAYMENT_BUCKETS,
} from "../../common/utils/paymentStatus";
import { DEFAULT_OPEN_PLAY_FEE } from "../../common/utils/settingsDefaults";
import { getOpenPlayPrice, buildRentalBookingIncomeBreakdown } from "../../common/utils/pricing";
import { isRentalBooking, toYMDLocal } from "../../common/utils/reportPrimitives";

const BookingManagerModal = React.lazy(() => import('../calendar/v2/BookingManagerModal'));

function formatDateTime(ts) {
  if (!ts) return "-";
  const d = new Date(ts);
  return d.toLocaleString([], { dateStyle: "medium", timeStyle: "short" });
}

function formatDate(ts) {
  if (!ts) return "-";
  return toYMDLocal(new Date(ts));
}

function formatCurrency(amount) {
  return new Intl.NumberFormat("en-PH", {
    style: "currency",
    currency: "PHP",
    maximumFractionDigits: 0,
  }).format(amount || 0);
}

function formatDuration(ms) {
  if (!ms || ms <= 0) return "-";
  const totalSeconds = Math.floor(ms / 1000);
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  return `${minutes}m ${seconds}s`;
}

function getMonthKey(date) {
  if (!date || isNaN(date.getTime())) return "";
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  return `${y}-${m}`;
}

export default function HistoryPage() {
  const {
    settings,
    opSessions = [],
    bookingsV2 = {},
    slotsV2 = {},
    updateOpSession,
    // V2 Actions
    updateBookingPaymentV2,
    updateBookingRenterV2,
    addSlotToBookingV2,
    removeSlotV2,
    toggleSlotPaymentV2,
    markAllSlotsPaidV2,
    markBookingFreeV2,
    deleteBookingV2,
    fetchBookingsForRange, // Added
    calendarCourts // Added
  } = useAppState(selectHistoryState);
  const [activeTab, setActiveTab] = useState("sessions"); // sessions | rentals
  const [monthFilter, setMonthFilter] = useState(() => getMonthKey(new Date()));
  const [selectedSessionId, setSelectedSessionId] = useState(null);
  const [detailsTab, setDetailsTab] = useState("players"); // players | payments | matches

  // V2 Modal State
  const [selectedBookingId, setSelectedBookingId] = useState(null);
  const [infoModal, setInfoModal] = useState({ isOpen: false, title: "", message: "" });
  const closeInfoModal = () => setInfoModal(prev => ({ ...prev, isOpen: false }));

  const handleAddSlot = (bookingId, slotData) => {
    try {
      addSlotToBookingV2(bookingId, slotData);
    } catch (e) {
      setInfoModal({ isOpen: true, title: "Cannot Add Slot", message: e.message });
    }
  };

  const handleCloseBookingModal = () => {
    setSelectedBookingId(null);
  };

  const activeBooking = selectedBookingId ? bookingsV2[selectedBookingId] : null;
  const activeBookingSlots = activeBooking ? activeBooking.slotIds.map(id => slotsV2[id]).filter(Boolean) : [];

  const handleUpdatePlayerPayment = (sessionId, playerId, partial) => {
    if (!updateOpSession) return;
    updateOpSession(sessionId, (session) => {
      const players = (session.players || []).map((p) =>
        p.id === playerId ? { ...p, ...partial } : p
      );
      return { ...session, players };
    });
  };

  // Settle Modal State (Added)
  const [settleModalOpen, setSettleModalOpen] = useState(false);
  const [settleTarget, setSettleTarget] = useState(null); // { sessionId, playerId, amount }

  const handleSettleSessionPlayer = (sessionId, playerId) => {
    const session = opSessions.find(s => s.id === sessionId);
    const player = session?.players?.find(p => p.id === playerId);
    const amount = player?.price || settings?.defaultOpFee || DEFAULT_OPEN_PLAY_FEE;
    setSettleTarget({ sessionId, playerId, amount });
    setSettleModalOpen(true);
  };

  const onSettleConfirm = (method) => {
    if (!settleTarget) return;
    const { sessionId, playerId } = settleTarget;

    const session = opSessions.find(s => s.id === sessionId);
    const player = session?.players?.find(p => p.id === playerId);
    const baseFee = settings?.defaultOpFee ?? DEFAULT_OPEN_PLAY_FEE;

    if (method === "unpaid") {
      handleUpdatePlayerPayment(sessionId, playerId, {
        paymentStatus: "unpaid",
        paymentMethod: null,
        price: 0,
      });
    } else if (method === "free") {
      handleUpdatePlayerPayment(sessionId, playerId, {
        paymentStatus: "free",
        paymentMethod: "free",
        price: 0,
      });
    } else {
      let price = typeof player?.price === "number" ? player.price : 0;
      if (price === 0) {
        price = getOpenPlayPrice(settings, {
          isMember: !!player?.isMember,
          sessionFee: session?.sessionFee ?? baseFee,
        });
      }
      handleUpdatePlayerPayment(sessionId, playerId, {
        paymentStatus: "paid",
        paymentMethod: method,
        price,
      });
    }
    setSettleModalOpen(false);
    setSettleTarget(null);
  };

  // When opening a session in History, backfill any missing prices for paid players
  // so older sessions created before pricing logic still show correct amounts.
  const openSessionDetails = (session) => {
    if (!session) {
      setSelectedSessionId(null);
      return;
    }

    const basePrice = settings?.defaultOpFee ?? DEFAULT_OPEN_PLAY_FEE;
    const hasMissingPrices = (session.players || []).some((p) => {
      const price = typeof p.price === "number" ? p.price : 0;
      return isPlayerPaid(p.paymentStatus, p.paymentMethod) && !isPlayerFree(p.paymentStatus, p.paymentMethod) && price <= 0;
    });

    if (hasMissingPrices && updateOpSession) {
      updateOpSession(session.id, (current) => {
        const updatedPlayers = (current.players || []).map((p) => {
          const price = typeof p.price === "number" ? p.price : 0;
          if (isPlayerPaid(p.paymentStatus, p.paymentMethod) && !isPlayerFree(p.paymentStatus, p.paymentMethod) && price <= 0) {
            return {
              ...p,
              price: getOpenPlayPrice(settings, {
                isMember: !!p.isMember,
                sessionFee: current.sessionFee ?? basePrice,
              }),
            };
          }
          return p;
        });
        return { ...current, players: updatedPlayers };
      });
    }

    setSelectedSessionId(session.id);
    setDetailsTab("players");
  };

  const filteredSessions = useMemo(() => {
    if (!Array.isArray(opSessions)) return [];

    // De-duplicate sessions by ID, preferring completed/populated ones
    const uniqueMap = new Map();
    opSessions.forEach(s => {
      const existing = uniqueMap.get(s.id);
      if (!existing) {
        uniqueMap.set(s.id, s);
      } else {
        // If we have a duplicate, keep the one with more data or is completed
        const isBetter = (s.players?.length || 0) > (existing.players?.length || 0) || s.status === 'completed';
        if (isBetter) {
          uniqueMap.set(s.id, s);
        }
      }
    });

    return Array.from(uniqueMap.values()).filter((s) => {
      const key = getMonthKey(new Date(s.startedAt || s.endedAt || Date.now()));
      return key === monthFilter;
    });
  }, [opSessions, monthFilter]);

  const filteredRentals = useMemo(() => {
    // V2 Logic: Filter bookingsV2 by month (via slots mostly, or created date? Usually slots determine "When")
    // Let's use the first slot time to determine the month key? Or updatedAt? 
    // Usually 'date' of booking. V2 bookings don't have a root date, slots do.
    // Logic: Find entries where at least one slot falls in the month.

    // Convert map to array
    const list = Object.values(bookingsV2);
    return list.filter((b) => {
      if (!isRentalBooking(b)) return false;
      // Find valid slots for this booking
      const bSlots = b.slotIds.map(id => slotsV2[id]).filter(s => s && s.status !== "CANCELLED"); // cancelled check if we ever set it

      if (bSlots.length === 0) {
        // console.log(`Debug: Booking ${b.id} has no valid slots. IDs:`, b.slotIds);
        return false;
      }

      // Check first slot date
      const first = bSlots[0];
      if (!first) return false;

      // Use string slice for filtering if date is present (safer than Date object)
      // slot.date is "YYYY-MM-DD"
      let key;
      if (first.date && typeof first.date === 'string') {
        key = first.date.substring(0, 7);
      } else {
        key = getMonthKey(new Date(first.startTime));
      }

      return key === monthFilter;
    }).sort((a, b) => {
      // Sort descending by date
      const sA = slotsV2[a.slotIds[0]]?.date || slotsV2[a.slotIds[0]]?.startTime;
      const sB = slotsV2[b.slotIds[0]]?.date || slotsV2[b.slotIds[0]]?.startTime;
      if (sA && sB) return sB.localeCompare(sA);
      return 0;
    });
  }, [bookingsV2, slotsV2, monthFilter]);

  const sessionRows = useMemo(
    () =>
      filteredSessions.map((s) => {
        const players = s.players || [];
        const matches = s.matches || [];
        const counts = { cash: 0, gcash: 0, gotyme: 0, bank: 0, notPaid: 0, free: 0 };
        players.forEach((p) => {
          const bucket = classifyPlayerPaymentBucket(p.paymentStatus, p.paymentMethod);
          if (PAID_PAYMENT_BUCKETS.includes(bucket)) counts[bucket] += 1;
          else if (bucket === "free") counts.free += 1;
          else counts.notPaid += 1;
        });
        const paidPlayers = PAID_PAYMENT_BUCKETS.reduce((sum, key) => sum + counts[key], 0) + counts.free;
        const income =
          String(s.status || "").toLowerCase() === "cancelled"
            ? 0
            : players.reduce(
                (sum, p) =>
                  sum +
                  (isPlayerPaidWithCharge(p.paymentStatus, p.paymentMethod)
                    ? typeof p.price === "number"
                      ? p.price
                      : 0
                    : 0),
                0
              );
        return {
          id: s.id,
          name: s.name,
          staffName: s.staffName || null,
          startedAt: s.startedAt,
          endedAt: s.endedAt,
          totalPlayers: players.length,
          totalMatches: s.totalMatches || matches.length,
          paidPlayers,
          income,
          raw: s,
        };
      }),
    [filteredSessions]
  );

  const rentalRows = useMemo(() => {
    return filteredRentals.map((b) => {
      const bSlots = b.slotIds.map((id) => slotsV2[id]).filter(Boolean).sort((x, y) => (x.startTime || 0) - (y.startTime || 0));
      if (!bSlots.length) return null;

      const first = bSlots[0];
      const last = bSlots[bSlots.length - 1];
      const dateStr = first.date || "";
      const startHour = Math.floor((first.startTime || 0) / 60);
      const endHour = Math.floor((last.endTime || 0) / 60);
      const formatHour = (h) => {
        const ampm = h >= 12 ? "PM" : "AM";
        const h12 = h % 12 || 12;
        return `${h12}${ampm}`;
      };
      const timeStr = `${formatHour(startHour)}-${formatHour(endHour)}`;
      const courtNames = [...new Set(bSlots.map((s) => s.courtId))].sort().join(", ");
      const renterName = b.renter?.name || "Walk-in";
      const breakdown = buildRentalBookingIncomeBreakdown(b, slotsV2, settings);
      const total = breakdown?.netDue ?? (b.paymentSummary?.totalAmount || 0);
      const status = breakdown?.paymentStatus || "UNPAID";

      return {
        id: b.id,
        date: dateStr,
        title: "Rental",
        renterName,
        renterId: b.renter?.contact || "",
        courtNames,
        timeLabel: timeStr,
        totalAmount: total,
        paymentStatus: status,
        breakdown,
        raw: b,
      };
    }).filter(Boolean);
  }, [filteredRentals, slotsV2, settings]);






  const handleExportSessions = () => {
    if (!sessionRows.length) return;
    const header = [
      "Session ID",
      "Name",
      "Started At",
      "Ended At",
      "Total Players",
      "Total Matches",
      "Paid Players",
      "Income PHP",
    ];
    const lines = [header.join(",")];
    sessionRows.forEach((row) => {
      lines.push(
        [
          row.id,
          JSON.stringify(row.name || ""),
          formatDateTime(row.startedAt),
          formatDateTime(row.endedAt),
          row.totalPlayers,
          row.totalMatches,
          row.paidPlayers,
          row.income,
        ].join(",")
      );
    });
    const csv = lines.join("\n");
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `op-sessions-${monthFilter}.csv`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleExportRentals = () => {
    if (!rentalRows.length) return;
    const header = [
      "Date",
      "Renter Name",
      "Renter ID",
      "Courts",
      "Time",
      "Total Amount",
      "Status",
      "Court Gross",
      "PickleCam",
      "Balls",
      "Discount",
      "Amount Paid",
      "Balance",
    ];
    const lines = [header.join(",")];
    rentalRows.forEach((g) => {
      const bd = g.breakdown || {};
      lines.push([
        g.date,
        JSON.stringify(g.renterName),
        g.renterId,
        `"Court ${g.courtNames}"`,
        g.timeLabel,
        g.totalAmount,
        g.paymentStatus,
        bd.courtGross ?? 0,
        bd.pickleCamPesos ?? 0,
        bd.ballsPesos ?? 0,
        bd.discountGiven ?? 0,
        bd.amountPaid ?? 0,
        bd.balance ?? 0,
      ].join(","));
    });

    const csv = lines.join("\n");
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `court-rentals-${monthFilter}.csv`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  // Standard Month List (Active Years based on data + Current Year)
  const uniqueMonths = useMemo(() => {
    const years = new Set();
    const today = new Date();
    years.add(today.getFullYear());

    const addYear = (d) => {
      if (d && !isNaN(d.getTime())) years.add(d.getFullYear());
    };

    (opSessions || []).forEach((s) => {
      addYear(new Date(s.startedAt || s.endedAt));
    });

    // Check slotsV2 for online data years
    Object.values(slotsV2 || {}).forEach((s) => {
      // s.date is YYYY-MM-DD string or s.startTime is minutes?
      // In V2 online, s.date is reliable.
      if (s.date) addYear(new Date(s.date));
    });

    const options = [];
    const sortedYears = Array.from(years).sort().reverse();

    sortedYears.forEach(year => {
      // For each year, generate months 0-11
      for (let m = 11; m >= 0; m--) {
        const d = new Date(year, m, 1);
        // Don't show future months
        // Compare YYYY-MM
        const currentKey = getMonthKey(d);
        const todayKey = getMonthKey(today);
        if (currentKey > todayKey) continue;

        options.push(currentKey);
      }
    });

    return [...new Set(options)];
  }, [opSessions, slotsV2]);

  // Fetch Data on Month Change
  React.useEffect(() => {
    if (!fetchBookingsForRange || !monthFilter) return;

    // Parse YYYY-MM
    const [y, m] = monthFilter.split('-').map(Number);
    // Start: YYYY-MM-01
    const start = new Date(y, m - 1, 1);
    // End: YYYY-MM-LastDay
    const end = new Date(y, m, 0);

    const sStr = start.toLocaleDateString('en-CA');
    const eStr = end.toLocaleDateString('en-CA');

    console.log(`History Page Fetching: ${sStr} to ${eStr}`);
    fetchBookingsForRange(sStr, eStr);
  }, [monthFilter, fetchBookingsForRange]);

  const selectedSession =
    selectedSessionId != null
      ? opSessions.find((s) => s.id === selectedSessionId) || null
      : null;

  const sessionAnalytics = useMemo(() => {
    if (!selectedSession) return null;

    const matches = Array.isArray(selectedSession.matches)
      ? selectedSession.matches.filter((m) => m && (m.durationMs || (m.startTime && m.endTime)))
      : [];
    const players = Array.isArray(selectedSession.players) ? selectedSession.players : [];

    if (!matches.length) {
      return {
        avgDurationMs: null,
        shortestMatch: null,
        longestMatch: null,
        mostActiveCourt: null,
        topPlayer: null,
      };
    }

    // Normalize durationMs for all matches
    const matchesWithDuration = matches.map((m) => {
      let durationMs = m.durationMs;
      if (!durationMs && m.startTime && m.endTime) {
        durationMs = Math.max(0, m.endTime - m.startTime);
      }
      return { ...m, durationMs };
    });

    const validMatches = matchesWithDuration.filter((m) => m.durationMs && m.durationMs > 0);
    if (!validMatches.length) {
      return {
        avgDurationMs: null,
        shortestMatch: null,
        longestMatch: null,
        mostActiveCourt: null,
        topPlayer: null,
      };
    }

    const totalDuration = validMatches.reduce((sum, m) => sum + (m.durationMs || 0), 0);
    const avgDurationMs = Math.round(totalDuration / validMatches.length);

    let shortestMatch = validMatches[0];
    let longestMatch = validMatches[0];
    validMatches.forEach((m) => {
      if (m.durationMs < shortestMatch.durationMs) shortestMatch = m;
      if (m.durationMs > longestMatch.durationMs) longestMatch = m;
    });

    const courtCounts = {};
    validMatches.forEach((m) => {
      const key = m.courtName || (m.courtId != null ? `Court ${m.courtId}` : "Unknown court");
      courtCounts[key] = (courtCounts[key] || 0) + 1;
    });
    let mostActiveCourt = null;
    Object.entries(courtCounts).forEach(([courtName, count]) => {
      if (!mostActiveCourt || count > mostActiveCourt.count) {
        mostActiveCourt = { courtName, count };
      }
    });

    const playerStats = {};
    validMatches.forEach((m) => {
      const winner = m.winner; // 'green', 'blue', 'tie'
      if (!winner) return;

      const processTeam = (teamIds, isWinner) => {
        (teamIds || []).forEach((id) => {
          if (!playerStats[id]) playerStats[id] = { wins: 0, total: 0 };
          playerStats[id].total += 1;
          if (isWinner) playerStats[id].wins += 1;
        });
      };

      processTeam(m.teams?.green, winner === "green");
      processTeam(m.teams?.blue, winner === "blue");
    });

    let topPlayer = null;
    Object.entries(playerStats).forEach(([id, stats]) => {
      if (stats.total < 2) return; // Min 2 matches to qualify for "Top Player"
      const winRate = (stats.wins / stats.total) * 100;
      const player = players.find((p) => String(p.id) === String(id));
      const name = player?.name || `P${id}`;

      if (!topPlayer || winRate > topPlayer.winRate || (winRate === topPlayer.winRate && stats.total > topPlayer.total)) {
        topPlayer = { id, name, winRate, total: stats.total, wins: stats.wins };
      }
    });

    return {
      avgDurationMs,
      shortestMatch,
      longestMatch,
      mostActiveCourt,
      topPlayer,
    };
  }, [selectedSession]);

  return (
    <div className="p-4 w-full h-full flex flex-col gap-4 overflow-hidden admin-page-bg">
      <SurfaceCard
        title="History"
        description="Browse past Open Play sessions and court rentals. Use month filter and export CSV for backups."
        actions={
          <div className="flex items-center gap-2 text-xs">
            <label className="text-slate-600">Month</label>
            <select
              value={monthFilter}
              onChange={(e) => {
                setMonthFilter(e.target.value);
                setSelectedBookingId(null);
                setSelectedSessionId(null);
              }}
              className="border rounded px-2 py-1 text-xs bg-white"
            >
              {uniqueMonths.map((m) => (
                <option key={m} value={m}>
                  {m}
                </option>
              ))}
            </select>
          </div>
        }
      >
        <p className="text-[11px] text-slate-500">
          Drill into sessions to adjust payments or review rentals for reconciliation.
        </p>
      </SurfaceCard>

      <SurfaceCard
        className="flex-1 min-h-0 flex flex-col"
        padded={false}
        bodyClassName="flex-1 min-h-0 flex flex-col"
      >
        <div className="px-4 pt-4 border-b border-slate-200 text-xs flex items-center gap-2">
          <button
            type="button"
            onClick={() => {
              setActiveTab("sessions");
              setSelectedSessionId(null);
            }}
            className={`px-3 py-1 -mb-px border-b-2 transition-colors ${activeTab === "sessions"
              ? "border-pt-orange text-pt-orange font-semibold"
              : "border-transparent text-slate-500 hover:text-slate-700"
              }`}
          >
            Open Play Sessions
          </button>
          <button
            type="button"
            onClick={() => {
              setActiveTab("rentals");
              setSelectedSessionId(null);
              setDetailsTab("players");
            }}
            className={`px-3 py-1 -mb-px border-b-2 transition-colors ${activeTab === "rentals"
              ? "border-pt-orange text-pt-orange font-semibold"
              : "border-transparent text-slate-500 hover:text-slate-700"
              }`}
          >
            Court Rentals
          </button>
        </div>

        <div className="flex-1 min-h-0 flex flex-col">
          {activeTab === "sessions" ? (
            <div className="flex flex-col h-full">
              <div className="px-4 py-2 flex items-center justify-between text-xs bg-slate-50 border-b border-slate-200">
                <span className="text-slate-700">
                  {sessionRows.length} session{sessionRows.length === 1 ? "" : "s"} in {monthFilter}
                </span>
                <button
                  type="button"
                  onClick={handleExportSessions}
                  disabled={!sessionRows.length}
                  className="px-3 py-1 rounded border text-xs bg-white text-slate-700 hover:bg-slate-50 disabled:opacity-40 disabled:cursor-not-allowed"
                >
                  Export CSV
                </button>
              </div>
              <div className="flex-1 overflow-auto text-xs">
                {sessionRows.length === 0 ? (
                  <p className="p-3 text-[11px] text-slate-500">No Open Play sessions for this month yet.</p>
                ) : (
                  <table className="min-w-full">
                    <thead className="bg-slate-50 text-[11px] text-slate-600 border-b">
                      <tr>
                        <th className="py-1 px-2 text-left">Date</th>
                        <th className="py-1 px-2 text-left">Name</th>
                        <th className="py-1 px-2 text-left">Started</th>
                        <th className="py-1 px-2 text-left">Ended</th>
                        <th className="py-1 px-2 text-right">Players</th>
                        <th className="py-1 px-2 text-right">Matches</th>
                        <th className="py-1 px-2 text-right">Paid</th>
                        <th className="py-1 px-2 text-right">Income</th>
                      </tr>
                    </thead>
                    <tbody>
                      {sessionRows.map((row) => (
                        <tr
                          key={row.id}
                          className="border-b last:border-b-0 cursor-pointer hover:bg-slate-50"
                          onClick={() => openSessionDetails(row.raw)}
                        >
                          <td className="py-1 px-2 whitespace-nowrap text-[11px] text-slate-700">
                            {formatDate(row.startedAt || row.endedAt)}
                          </td>
                          <td className="py-1 px-2 max-w-[260px] truncate text-[11px] text-slate-800">
                            <span className="inline-flex items-center gap-2">
                              <span className="truncate max-w-[200px]">{row.name}</span>
                              {String(row.raw?.status || "").toLowerCase() === "cancelled" && (
                                <span className="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] border bg-red-50 text-red-700 border-red-200">
                                  Cancelled
                                </span>
                              )}
                            </span>
                          </td>
                          <td className="py-1 px-2 whitespace-nowrap text-[11px] text-slate-600">
                            {formatDateTime(row.startedAt)}
                          </td>
                          <td className="py-1 px-2 whitespace-nowrap text-[11px] text-slate-600">
                            {formatDateTime(row.endedAt)}
                          </td>
                          <td className="py-1 px-2 text-right text-[11px] text-slate-700">
                            {row.totalPlayers}
                          </td>
                          <td className="py-1 px-2 text-right text-[11px] text-slate-700">
                            {row.totalMatches}
                          </td>
                          <td className="py-1 px-2 text-right text-[11px] text-emerald-700">
                            {row.paidPlayers}
                          </td>
                          <td className="py-1 px-2 text-right text-[11px] font-semibold text-slate-900">
                            {formatCurrency(row.income)}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                )}
              </div>
            </div>
          ) : (
            <div className="flex flex-col h-full">
              <div className="px-4 py-2 flex items-center justify-between text-xs bg-slate-50 border-b border-slate-200">
                <span className="text-slate-700">
                  {rentalRows.length} rental{rentalRows.length === 1 ? "" : "s"} in {monthFilter}
                </span>
                <button
                  type="button"
                  onClick={handleExportRentals}
                  disabled={!rentalRows.length}
                  className="px-3 py-1 rounded border text-xs bg-white text-slate-700 hover:bg-slate-50 disabled:opacity-40 disabled:cursor-not-allowed"
                >
                  Export CSV
                </button>
              </div>
              <div className="flex-1 overflow-auto text-xs">
                {rentalRows.length === 0 ? (
                  <p className="p-3 text-[11px] text-slate-500">No rentals for this month yet.</p>
                ) : (
                  <table className="min-w-full">
                    <thead className="bg-slate-50 text-[11px] text-slate-600 border-b">
                      <tr>
                        <th className="py-1 px-2 text-left">Date</th>
                        <th className="py-1 px-2 text-left">Renter</th>
                        <th className="py-1 px-2 text-left">Courts</th>
                        <th className="py-1 px-2 text-left">Time</th>
                        <th className="py-1 px-2 text-left">Status</th>
                        <th className="py-1 px-2 text-right">Total</th>
                        <th className="py-1 px-2 text-center">Action</th>
                      </tr>
                    </thead>
                    <tbody>
                      {rentalRows.map((group) => (
                        <tr
                          key={group.id}
                          className="border-b last:border-b-0 cursor-pointer hover:bg-slate-50"
                          onClick={() => setSelectedBookingId(group.id)}
                        >
                          <td className="py-1 px-2 whitespace-nowrap text-[11px] text-slate-700">
                            {group.date}
                          </td>
                          <td className="py-1 px-2 max-w-[200px] truncate text-[11px] text-slate-800">
                            <div className="font-semibold">{group.title}</div>
                            <div className="text-[10px] text-slate-500">
                              <span>👤 {group.renterName}</span>
                            </div>
                          </td>
                          <td className="py-1 px-2 whitespace-nowrap text-[11px] text-slate-600">
                            {group.courtNames}
                          </td>
                          <td className="py-1 px-2 whitespace-nowrap text-[11px] text-slate-600">
                            {group.timeLabel}
                          </td>
                          <td className="py-1 px-2 whitespace-nowrap text-[11px]">
                            <span
                              className={`inline-flex items-center px-2 py-0.5 rounded-full text-[10px] border ${String(group.paymentStatus).toUpperCase() === "CANCELLED"
                                ? "bg-red-50 text-red-700 border-red-200"
                                : ["PAID", "FREE"].includes(String(group.paymentStatus).toUpperCase())
                                  ? "bg-emerald-50 text-emerald-700 border-emerald-200"
                                  : "bg-amber-50 text-amber-700 border-amber-200"
                                }`}
                            >
                              {group.paymentStatus}
                            </span>
                          </td>
                          <td className="py-1 px-2 text-right text-[11px] font-semibold text-slate-900">
                            {formatCurrency(group.totalAmount)}
                          </td>
                          <td className="py-1 px-2 text-center">
                            <button
                              onClick={(e) => {
                                e.stopPropagation();
                                setSelectedBookingId(group.id);
                              }}
                              className="text-[10px] bg-white border border-slate-200 hover:bg-slate-100 text-slate-600 px-2 py-1 rounded shadow-sm"
                            >
                              View
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                )}
              </div>
            </div>
          )}
        </div>
      </SurfaceCard >

      {selectedSession && activeTab === "sessions" && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 px-2">
          <SurfaceCard
            className="max-w-4xl w-full max-h-[90vh]"
            padded={false}
            bodyClassName="flex flex-col text-xs max-h-[90vh]"
          >
            <div className="px-4 pt-3 pb-2 border-b border-slate-200 flex items-start justify-between gap-3">
              <div>
                <div className="text-[11px] uppercase tracking-wide text-slate-500 mb-0.5">
                  Open Play session summary
                </div>
                <div className="text-sm font-semibold text-slate-900 flex items-center gap-2">
                  <span>{selectedSession.name}</span>
                  {String(selectedSession.status || "").toLowerCase() === "cancelled" && (
                    <span className="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] border bg-red-50 text-red-700 border-red-200">
                      Cancelled
                    </span>
                  )}
                </div>
                <div className="text-[11px] text-slate-500 mt-0.5">
                  {formatDateTime(selectedSession.startedAt)} – {formatDateTime(selectedSession.endedAt)}
                </div>
                {selectedSession.staffName && (
                  <div className="text-[11px] text-slate-500 mt-0.5">
                    Staff: <span className="font-medium text-slate-700">{selectedSession.staffName}</span>
                  </div>
                )}
                {String(selectedSession.status || "").toLowerCase() === "cancelled" && selectedSession.cancelReason && (
                  <div className="mt-1 text-[11px] text-red-700">
                    Reason: {selectedSession.cancelReason}
                  </div>
                )}
                <div className="mt-2">
                  <label className="block text-[10px] uppercase tracking-wide text-slate-400 mb-0.5">
                    Session notes
                  </label>
                  <textarea
                    className="w-full border border-slate-200 rounded-lg px-2 py-1 text-[11px] resize-none bg-slate-50 focus:bg-white focus:outline-none focus:ring-1 focus:ring-slate-400 focus:border-slate-400"
                    rows={2}
                    placeholder="Notes about this session (e.g. late start, special event, discounts)"
                    value={selectedSession.notes || ""}
                    onChange={(e) => {
                      if (!updateOpSession) return;
                      updateOpSession(selectedSession.id, (session) => ({
                        ...session,
                        notes: e.target.value,
                      }));
                    }}
                  />
                </div>
              </div>
              <button
                type="button"
                onClick={() => setSelectedSessionId(null)}
                className="text-[11px] px-3 py-1.5 rounded-full border border-slate-200 text-slate-600 hover:bg-slate-50"
              >
                Close
              </button>
            </div>
            <div className="px-4 pt-2 pb-1 border-b border-slate-200 flex items-center justify-between gap-2 text-[11px] bg-slate-50/60">
              <div className="flex items-center gap-3">
                <span className="text-slate-700">
                  {selectedSession.totalPlayers ?? (selectedSession.players || []).length} players
                  {" • "}
                  {selectedSession.totalMatches ?? (selectedSession.matches || []).length} matches
                </span>
              </div>
              <div className="inline-flex items-center rounded-full border border-slate-200 bg-white px-1 py-0.5 text-[11px]">
                <button
                  type="button"
                  onClick={() => setDetailsTab("players")}
                  className={`px-3 py-0.5 rounded-full ${detailsTab === "players"
                    ? "bg-slate-900 text-white"
                    : "text-slate-700 hover:bg-slate-100"
                    }`}
                >
                  Players
                </button>
                <button
                  type="button"
                  onClick={() => setDetailsTab("matches")}
                  className={`px-3 py-0.5 rounded-full ${detailsTab === "matches"
                    ? "bg-slate-900 text-white"
                    : "text-slate-700 hover:bg-slate-100"
                    }`}
                >
                  Match History
                </button>
              </div>
            </div>
            <div className="flex-1 min-h-0 overflow-auto p-4 space-y-3">
              {detailsTab === "players" && (
                <div>
                  <div className="mb-3 text-[11px] text-slate-500 flex items-center justify-between">
                    <span>Update payment status, price, and notes for players in this session.</span>
                    <span className="text-slate-400">
                      Default fee: ₱{settings?.defaultOpFee ?? DEFAULT_OPEN_PLAY_FEE}
                    </span>
                  </div>
                  <div className="border border-slate-200 rounded-2xl overflow-hidden bg-white">
                    <table className="min-w-full text-[11px]">
                      <thead className="bg-slate-100/80 text-slate-600 border-b border-slate-200 uppercase tracking-wide text-[10px]">
                        <tr>
                          <th className="px-2 py-1 text-left">Arrival</th>
                          <th className="px-2 py-1 text-left">Departure</th>
                          <th className="px-2 py-1 text-left">Player</th>
                          <th className="px-2 py-1 text-left">Level</th>
                          <th className="px-2 py-1 text-left">Gender</th>
                          <th className="px-2 py-1 text-left">Payment</th>
                          <th className="px-2 py-1 text-right">Price</th>
                          <th className="px-2 py-1 text-left">Notes</th>
                          <th className="px-2 py-1 text-right">Matches</th>
                          <th className="px-2 py-1 text-right">Longest wait</th>
                          <th className="px-2 py-1 text-right">Avg match</th>
                        </tr>
                      </thead>
                      <tbody>
                        {(selectedSession.players || []).map((p, index) => (
                          <tr
                            key={p.id}
                            className={`border-b last:border-b-0 align-top ${!p.arrivalTime
                                ? "opacity-60 bg-slate-100/80"
                                : index % 2 === 0
                                  ? "bg-white"
                                  : "bg-slate-50/60"
                              }`}
                          >
                            {/* Arrival */}
                            <td className="px-2 py-3 whitespace-nowrap text-slate-600 font-mono text-[10px]">
                              {p.arrivalTime || p.joinedAt ? (
                                new Date(p.arrivalTime || p.joinedAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
                              ) : (
                                <span className="inline-flex items-center px-1.5 py-0.5 rounded text-[9px] bg-slate-200 text-slate-500 font-medium tracking-wide">No show</span>
                              )}
                            </td>
                            {/* Departure */}
                            <td className="px-2 py-3 whitespace-nowrap text-slate-500 font-mono text-[10px]">
                              {p.departureTime
                                ? new Date(p.departureTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
                                : <span className="text-slate-300">-</span>}
                            </td>
                            <td className="px-2 py-3 whitespace-nowrap text-slate-800">
                              <span className="font-medium">{p.name}</span>
                            </td>
                            <td className="px-2 py-3 whitespace-nowrap text-slate-600">{p.level || "-"}</td>
                            <td className="px-2 py-3 whitespace-nowrap text-slate-600">{p.gender || "-"}</td>
                            <td className="px-2 py-3 whitespace-nowrap">
                              <button
                                onClick={() => {
                                  if (String(selectedSession.status || "").toLowerCase() === "cancelled") return;
                                  handleSettleSessionPlayer(selectedSession.id, p.id);
                                }}
                                className={`px-2 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-wide border transition-all ${isPlayerPaid(p.paymentStatus, p.paymentMethod) && !isPlayerFree(p.paymentStatus, p.paymentMethod)
                                  ? 'bg-emerald-50 text-emerald-700 border-emerald-200 hover:bg-emerald-100'
                                  : isPlayerFree(p.paymentStatus, p.paymentMethod)
                                    ? 'bg-slate-50 text-slate-600 border-slate-200 hover:bg-slate-100'
                                    : 'bg-amber-50 text-amber-700 border-amber-200 hover:bg-amber-100 animate-pulse'
                                  }`}
                              >
                                {isPlayerUnpaid(p.paymentStatus, p.paymentMethod)
                                  ? 'Unpaid'
                                  : isPlayerFree(p.paymentStatus, p.paymentMethod)
                                    ? 'Free'
                                    : normalizePaymentMethod(p.paymentStatus, p.paymentMethod)}
                              </button>
                            </td>
                            <td className="px-2 py-3 whitespace-nowrap text-right align-middle">
                              <input
                                type="number"
                                className="w-20 border border-slate-200 rounded-full px-2 py-1 text-[11px] text-right bg-white shadow-sm focus:outline-none focus:ring-1 focus:ring-slate-400 focus:border-slate-400"
                                value={typeof p.price === "number" ? p.price : 0}
                                min={0}
                                onChange={(e) =>
                                  handleUpdatePlayerPayment(selectedSession.id, p.id, {
                                    price: Number(e.target.value) || 0,
                                  })
                                }
                                disabled={String(selectedSession.status || "").toLowerCase() === "cancelled"}
                              />
                            </td>
                            <td className="px-2 py-3 min-w-[160px]">
                              <textarea
                                className="w-full border border-slate-200 rounded-lg px-2 py-1 text-[11px] resize-none bg-slate-50 focus:bg-white focus:outline-none focus:ring-1 focus:ring-slate-400 focus:border-slate-400"
                                rows={1}
                                placeholder="Notes (e.g. late payment, discount, no-show)"
                                value={p.notes || ""}
                                onChange={(e) =>
                                  handleUpdatePlayerPayment(selectedSession.id, p.id, {
                                    notes: e.target.value,
                                  })
                                }
                                disabled={String(selectedSession.status || "").toLowerCase() === "cancelled"}
                              />
                            </td>
                            <td className="px-2 py-3 text-right whitespace-nowrap text-slate-700">
                              {p.matches ?? 0}
                            </td>
                            <td className="px-2 py-3 text-right whitespace-nowrap text-slate-700">
                              {p.longestWaitTimeMs
                                ? `${Math.floor(p.longestWaitTimeMs / 60000)}m ${Math.floor(
                                  (p.longestWaitTimeMs % 60000) / 1000
                                )}s`
                                : "-"}
                            </td>
                            <td className="px-2 py-3 text-right whitespace-nowrap text-slate-700">
                              {p.averageMatchDurationMs
                                ? `${Math.floor(p.averageMatchDurationMs / 60000)}m ${Math.floor(
                                  (p.averageMatchDurationMs % 60000) / 1000
                                )}s`
                                : "-"}
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              )}
              {detailsTab === "matches" && (
                <div className="text-[11px] text-slate-600">
                  {sessionAnalytics && (
                    <div className="mb-3 flex flex-col gap-2 text-[11px]">
                      <div className="flex flex-wrap gap-2 items-center">
                        <span className="uppercase tracking-wide text-[10px] text-slate-500">
                          Session summary
                        </span>
                        <div className="inline-flex flex-wrap gap-2">
                          <span className="inline-flex items-center px-2.5 py-1 rounded-full bg-slate-100 text-slate-800 border border-slate-200">
                            <span className="text-[10px] uppercase mr-1 text-slate-500">Avg match</span>
                            <span className="font-semibold">
                              {sessionAnalytics.avgDurationMs
                                ? formatDuration(sessionAnalytics.avgDurationMs)
                                : "-"}
                            </span>
                          </span>
                          <span className="inline-flex items-center px-2.5 py-1 rounded-full bg-slate-100 text-slate-800 border border-slate-200">
                            <span className="text-[10px] uppercase mr-1 text-slate-500">Shortest</span>
                            <span className="font-semibold">
                              {sessionAnalytics.shortestMatch?.durationMs
                                ? formatDuration(sessionAnalytics.shortestMatch.durationMs)
                                : "-"}
                            </span>
                          </span>
                          <span className="inline-flex items-center px-2.5 py-1 rounded-full bg-slate-100 text-slate-800 border border-slate-200">
                            <span className="text-[10px] uppercase mr-1 text-slate-500">Longest</span>
                            <span className="font-semibold">
                              {sessionAnalytics.longestMatch?.durationMs
                                ? formatDuration(sessionAnalytics.longestMatch.durationMs)
                                : "-"}
                            </span>
                          </span>
                          <span className="inline-flex items-center px-2.5 py-1 rounded-full bg-slate-100 text-slate-800 border border-slate-200">
                            <span className="text-[10px] uppercase mr-1 text-slate-500">Most active court</span>
                            <span className="font-semibold">
                              {sessionAnalytics.mostActiveCourt
                                ? `${sessionAnalytics.mostActiveCourt.courtName} · ${sessionAnalytics.mostActiveCourt.count} match${sessionAnalytics.mostActiveCourt.count === 1 ? "" : "es"}`
                                : "-"}
                            </span>
                          </span>
                          <span className="inline-flex items-center px-2.5 py-1 rounded-full bg-slate-100 text-slate-800 border border-slate-200">
                            <span className="text-[10px] uppercase mr-1 text-slate-500">Top player</span>
                            <span className="font-semibold">
                              {sessionAnalytics.topPlayer
                                ? `${sessionAnalytics.topPlayer.name} · ${Math.round(sessionAnalytics.topPlayer.winRate)}% (${sessionAnalytics.topPlayer.wins}/${sessionAnalytics.topPlayer.total})`
                                : "-"}
                            </span>
                          </span>
                        </div>
                      </div>
                    </div>
                  )}
                  <p className="mb-1 text-slate-700 font-semibold">Match history</p>
                  <div className="border border-slate-200 rounded-lg overflow-hidden mt-2">
                    <table className="min-w-full text-[11px]">
                      <thead className="bg-slate-50 text-slate-600 border-b border-slate-200">
                        <tr>
                          <th className="px-2 py-1 text-left">Court</th>
                          <th className="px-2 py-1 text-left">Start</th>
                          <th className="px-2 py-1 text-left">End</th>
                          <th className="px-2 py-1 text-right">Duration</th>
                          <th className="px-2 py-1 text-left">Teams</th>
                          <th className="px-2 py-1 text-right">Score</th>
                          <th className="px-2 py-1 text-right">Winner</th>
                        </tr>
                      </thead>
                      <tbody>
                        {(selectedSession.matches || []).map((m) => {
                          const durationLabel = m.durationMs
                            ? `${Math.floor(m.durationMs / 60000)}m ${Math.floor(
                              (m.durationMs % 60000) / 1000
                            )}s`
                            : "-";
                          const hasTeams = (m.teams?.green?.length > 0) || (m.teams?.blue?.length > 0);
                          const teamGreenNames = (m.teams?.green || [])
                            .map((id) =>
                              (selectedSession.players || []).find((p) => p.id === id)?.name || `P${id}`
                            )
                            .join(", ");
                          const teamBlueNames = (m.teams?.blue || [])
                            .map((id) =>
                              (selectedSession.players || []).find((p) => p.id === id)?.name || `P${id}`
                            )
                            .join(", ");


                          // If m.players is array of objects, use it. If m.playerIds, map it. 
                          // Fallback logic improved:

                          let playerNamesArray = [];
                          if (!hasTeams) {
                            if (m.lineup && m.lineup.length) {
                              playerNamesArray = m.lineup.map(p => p.name);
                            } else if (m.players && m.players.length) {
                              playerNamesArray = m.players.map(p => p.name);
                            } else if (m.playerIds && m.playerIds.length) {
                              playerNamesArray = m.playerIds
                                .map(id => (selectedSession.players || []).find(p => p.id === id)?.name || "Unknown");
                            }
                          }

                          const scoreGreen = m.score?.green ?? null;
                          const scoreBlue = m.score?.blue ?? null;
                          const scoreLabel =
                            scoreGreen != null && scoreBlue != null ? `${scoreGreen}–${scoreBlue}` : "-";
                          const winnerLabel =
                            m.winner === "green"
                              ? "Green"
                              : m.winner === "blue"
                                ? "Blue"
                                : m.winner === "tie"
                                  ? "Tie"
                                  : "-";
                          return (
                            <tr key={m.id} className="border-b last:border-b-0">
                              <td className="px-2 py-1 whitespace-nowrap text-slate-700">
                                {m.courtName || `Court ${m.courtId ?? "-"}`}
                              </td>
                              <td className="px-2 py-1 whitespace-nowrap text-slate-600">
                                {m.startTime ? formatDateTime(m.startTime) : "-"}
                              </td>
                              <td className="px-2 py-1 whitespace-nowrap text-slate-600">
                                {m.endTime ? formatDateTime(m.endTime) : "-"}
                              </td>
                              <td className="px-2 py-1 text-right whitespace-nowrap text-slate-700">{durationLabel}</td>
                              <td className="px-2 py-1 text-left whitespace-pre-wrap text-slate-700">
                                {hasTeams ? (
                                  <>
                                    <span className="block"><span className="font-semibold">Green:</span> {teamGreenNames}</span>
                                    <span className="block"><span className="font-semibold">Blue:</span> {teamBlueNames}</span>
                                  </>
                                ) : (
                                  <div className="flex flex-wrap gap-1">
                                    {playerNamesArray.length > 0 ? (
                                      playerNamesArray.map((name, idx) => (
                                        <span key={idx} className="inline-block bg-slate-100 text-slate-700 px-1.5 py-0.5 rounded text-[10px] border border-slate-200">
                                          {name}
                                        </span>
                                      ))
                                    ) : (
                                      <span className="text-slate-400 italic">No players recorded</span>
                                    )}
                                  </div>
                                )}
                              </td>
                              <td className="px-2 py-1 text-right whitespace-nowrap text-slate-700">{scoreLabel}</td>
                              <td className="px-2 py-1 text-right whitespace-nowrap text-slate-700">{winnerLabel}</td>
                            </tr>
                          );
                        })}
                      </tbody>
                    </table>
                  </div>
                </div>
              )}
            </div>
          </SurfaceCard>
        </div>
      )
      }


      <SettlePaymentModal
        isOpen={settleModalOpen}
        onClose={() => setSettleModalOpen(false)}
        onSettle={onSettleConfirm}
        amount={settleTarget?.amount}
        title="Settle Player Payment"
      />
      <React.Suspense fallback={null}>
        <BookingManagerModal
          isOpen={!!activeBooking}
          onClose={handleCloseBookingModal}
          booking={activeBooking}
          slots={activeBookingSlots}
          allSlots={Object.values(slotsV2 || {})}
          onUpdateRenter={updateBookingRenterV2}
          onUpdatePayment={updateBookingPaymentV2}
          onAddSlot={handleAddSlot}
          onRemoveSlot={removeSlotV2}
          onToggleSlotPayment={toggleSlotPaymentV2}
          onMarkAllPaid={markAllSlotsPaidV2}
          onMarkFree={markBookingFreeV2}
          isCreating={false}
          onDeleteBooking={deleteBookingV2}
          readOnly={true}
          courts={calendarCourts}
          settings={settings}
          defaultRentalRate={settings?.defaultRentalRate}
        />
      </React.Suspense>
      <ConfirmationModal
        isOpen={infoModal.isOpen}
        title={infoModal.title}
        message={infoModal.message}
        confirmLabel="OK"
        cancelLabel={null}
        onConfirm={closeInfoModal}
        onCancel={closeInfoModal}
      />
    </div >
  );
}

