import React from "react";
import { Routes, Route, Navigate, useLocation } from "react-router-dom";
import { useAppState } from "./app/providers";
import { selectQueueState } from "./state/selectors";

import { DisplayPage } from "./features/display";
import HistoryPage from "./features/history/HistoryPage";
import DashboardV2Page from "./features/dashboard/DashboardV2Page";
import SettingsPage from "./features/settings/SettingsPage";
import ReportPrintPage from "./features/reports/ReportPrintPage";
import AppShell from "./app/AppShell";
import LandingPage from "./features/auth/LandingPage";
import VersionPage from "./features/misc/VersionPage";
import useInactivityTimer from "./features/auth/useInactivityTimer"; // Import new hook
import GlobalErrorBoundary from "./components/GlobalErrorBoundary";
import { Toaster } from 'react-hot-toast';

import CalendarPage from './features/calendar/CalendarPage';
import CalendarV2Page from './features/calendar/CalendarV2Page';
import QueuePage from './features/queue/QueuePage';


function ProtectedRoute({ children, allowedRoles = [] }) {
  const { userRole } = useAppState(selectQueueState);
  const location = useLocation();

  if (!userRole) {
    // Not logged in -> Redirect to Landing
    return <Navigate to="/" state={{ from: location }} replace />;
  }

  if (allowedRoles.length > 0 && !allowedRoles.includes(userRole)) {
    // Role not allowed -> Redirect to Landing (re-challenge)
    return <Navigate to="/" replace />;
  }

  return children;
}

export default function App() {
  const { userRole, logout } = useAppState(selectQueueState); // Destructure userRole and logout from useAppState

  // Activate Inactivity Timer (1 Hour)
  useInactivityTimer({ userRole, logout, timeoutMs: 3600000 });

  return (
    <GlobalErrorBoundary>
      <Toaster position="top-center" />
      <Routes>
        <Route path="/" element={<LandingPage />} />
        <Route path="/display" element={<DisplayPage />} />
        <Route path="/version" element={<VersionPage />} />

        {/* ADMIN ONLY ROUTES */}
        <Route
          path="/dashboard"
          element={
            <ProtectedRoute allowedRoles={["admin"]}>
              <AppShell>
                <DashboardV2Page />
              </AppShell>
            </ProtectedRoute>
          }
        />

        <Route
          path="/history"
          element={
            <ProtectedRoute allowedRoles={["admin"]}>
              <AppShell>
                <HistoryPage />
              </AppShell>
            </ProtectedRoute>
          }
        />

        <Route
          path="/settings"
          element={
            <ProtectedRoute allowedRoles={["admin"]}>
              <AppShell>
                <SettingsPage />
              </AppShell>
            </ProtectedRoute>
          }
        />

        <Route path="/reports/print" element={<ReportPrintPage />} />

        {/* STAFF & ADMIN ROUTES */}
        <Route
          path="/queue"
          element={
            <ProtectedRoute allowedRoles={["staff", "admin"]}>
              <AppShell>
                <QueuePage />
              </AppShell>
            </ProtectedRoute>
          }
        />

        <Route
          path="/calendar"
          element={
            <ProtectedRoute allowedRoles={["staff", "admin"]}>
              <AppShell>
                <CalendarPage />
              </AppShell>
            </ProtectedRoute>
          }
        />

        <Route
          path="/calendar-v2"
          element={
            <ProtectedRoute allowedRoles={["staff", "admin"]}>
              <AppShell>
                <CalendarV2Page />
              </AppShell>
            </ProtectedRoute>
          }
        />

        {/* Fallback */}
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </GlobalErrorBoundary>
  );
}
