import { isOpenPlayCalendarBlock } from "./openPlayBlock";

const asNumber = (value, fallback = 0) => {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
};

export const isWeekendDate = (dateLike) => {
  const date = dateLike instanceof Date ? dateLike : new Date(`${dateLike}T00:00:00`);
  const day = Number.isFinite(date.getTime()) ? date.getDay() : new Date().getDay();
  // Fri–Sun use weekend rental rates
  return day === 0 || day === 5 || day === 6;
};

export const getOpenPlayPrice = (settings = {}, { isMember = false, sessionFee = null } = {}) => {
  const base = asNumber(sessionFee, asNumber(settings.defaultOpFee, 0));
  const discount = isMember ? asNumber(settings.memberDiscount, 0) : 0;
  return Math.max(0, base - discount);
};

export const getRentalSlotPrice = (settings = {}, { date, startTime } = {}) => {
  const rates = settings.rentalRates || {};
  const period = isWeekendDate(date) ? "weekend" : "weekday";
  const startHour = Math.floor(asNumber(startTime, 0) / 60);
  const highStartHour = asNumber(rates.highStartHour, 15);
  const fallbackRate = asNumber(settings.defaultRentalRate, 0);
  const periodRates = rates[period] || {};
  const rateKey = startHour >= highStartHour ? "high" : "low";
  return asNumber(periodRates[rateKey], fallbackRate);
};

/** One row per hour for add-slot preview and validation (endHour is exclusive). */
export const buildHourlySlotPreview = (settings = {}, { date, startHour, endHour } = {}) => {
  const sH = Math.floor(asNumber(startHour, 0));
  const eH = Math.floor(asNumber(endHour, 0));
  if (!date || eH <= sH) return [];
  const rows = [];
  for (let h = sH; h < eH; h += 1) {
    const startTime = h * 60;
    rows.push({
      startHour: h,
      endHour: h + 1,
      startTime,
      endTime: (h + 1) * 60,
      price: getRentalSlotPrice(settings, { date, startTime }),
    });
  }
  return rows;
};

export const sumRentalSlots = (slots = []) =>
  slots.reduce((sum, slot) => sum + asNumber(slot?.price, 0), 0);

/** Court-hours for one slot (supports minute offsets or ISO timestamps). */
export const computeSlotCourtHours = (slot) => {
  if (!slot) return 0;
  if (typeof slot.startTime === "number" && typeof slot.endTime === "number") {
    return Math.max(0, (slot.endTime - slot.startTime) / 60);
  }
  const start = new Date(slot.startTime);
  const end = new Date(slot.endTime);
  if (!Number.isFinite(start.getTime()) || !Number.isFinite(end.getTime())) return 0;
  return Math.max(0, (end - start) / (1000 * 60 * 60));
};

/** Total court-hours across active rental slots. */
export const sumSlotCourtHours = (slots = []) =>
  (slots || []).reduce((sum, slot) => sum + computeSlotCourtHours(slot), 0);

/** PickleCam total = rate × chosen hours (hourly mode). */
export const computePickleCamTotalFromHours = (hours = 0, ratePerHour = 25) => {
  const rate = asNumber(ratePerHour, 25);
  const h = Math.max(0, asNumber(hours, 0));
  return Math.round(rate * h);
};

/** @deprecated Legacy helper — prefer computePickleCamTotalFromHours with explicit hours. */
export const computePickleCamTotal = (slots = [], ratePerCourtHour = 25, enabled = true) => {
  if (!enabled) return 0;
  return computePickleCamTotalFromHours(sumSlotCourtHours(slots), ratePerCourtHour);
};

export const getPickleCamPricingMode = (renter = {}) =>
  renter?.pickleCamPricingMode === "hourly" ? "hourly" : "flat";

export const PICKLECAM_MAX_COURTS = 5;

/** PickleCam courts used (1–5). Defaults to 1 when unset. */
export const resolvePickleCamCourtCount = (renter = {}) => {
  const stored = Math.floor(asNumber(renter.pickleCamCourtCount, 0));
  if (stored >= 1) return Math.min(PICKLECAM_MAX_COURTS, stored);
  return 1;
};

export const resolvePickleCamHours = (renter = {}, slots = []) => {
  const stored = asNumber(renter.pickleCamHours, 0);
  if (stored > 0) return stored;
  if (getPickleCamPricingMode(renter) === "hourly") {
    const slotHours = sumSlotCourtHours(slots);
    return slotHours > 0 ? slotHours : 1;
  }
  return 0;
};

export const computePickleCamCharge = (renter = {}, slots = [], fallbackRate = 25) => {
  if (!renter?.pickleCam) return 0;
  if (getPickleCamPricingMode(renter) === "hourly") {
    const rate = asNumber(renter.pickleCamFee, fallbackRate);
    const hours = resolvePickleCamHours(renter, slots);
    const courts = resolvePickleCamCourtCount(renter);
    return Math.round(rate * hours * courts);
  }
  return asNumber(renter.pickleCamFee, 0);
};

export const computeBallSalesTotal = (renter = {}, fallbackUnitPrice = 78) => {
  const qty = Math.max(0, Math.floor(asNumber(renter.ballQty, 0)));
  if (qty <= 0) return 0;
  const unit = asNumber(renter.ballFee, fallbackUnitPrice);
  return qty * unit;
};

/** Slot sum + add-ons − discount % (matches booking modal / calendar manager). */
export const computeRentalBookingTotal = (booking, slots = [], settings = {}) => {
  const slotTotal = sumRentalSlots(slots);
  const renter = booking?.renter || {};
  const pickleCamTotal = computePickleCamCharge(renter, slots, asNumber(settings.pickleCamFee, 25));
  const ballTotal = computeBallSalesTotal(renter, asNumber(settings.ballFee, 78));
  const raw = slotTotal + pickleCamTotal + ballTotal;
  const discountPct = asNumber(renter.discount, 0);
  const discountOff = Math.round(raw * (discountPct / 100));
  return Math.max(0, raw - discountOff);
};

/** Resolve total due, paid, and outstanding balance for dashboard / reports. */
export const getRentalBookingFinancials = (booking, slotsV2 = {}) => {
  const slots = Object.values(slotsV2).filter(
    (s) => s && s.bookingId === booking?.id && s.status !== "CANCELLED"
  );
  const computedTotal = computeRentalBookingTotal(booking, slots);
  const amountPaid = asNumber(booking?.paymentSummary?.amountPaid, 0);
  const storedTotal = asNumber(booking?.paymentSummary?.totalAmount, 0);

  // Prefer the stored total (mirrors the calendar DB total_price) so reports match
  // the booking's recorded payment. Only fall back to the live slot total when no
  // stored total exists, otherwise recomputed slot prices create phantom balances.
  const totalDue = storedTotal > 0 ? storedTotal : computedTotal;

  // Negative balance = overpaid (refundable). Do not clamp to 0.
  const balance = totalDue - amountPaid;
  let paymentStatus = "UNPAID";
  const method = String(booking?.paymentSummary?.paymentMethod || "").toUpperCase();
  if (method === "FREE") {
    paymentStatus = "FREE";
  } else if (balance <= 0 && amountPaid > 0) {
    paymentStatus = "PAID";
  } else if (amountPaid > 0) {
    paymentStatus = "PARTIAL";
  }

  return { slots, totalDue, amountPaid, balance, paymentStatus };
};

const computeDiscountGiven = (renter = {}, grossBeforeDiscount = 0) => {
  const discountPct = asNumber(renter.discount, 0);
  if (discountPct > 0) {
    return Math.round(grossBeforeDiscount * (discountPct / 100));
  }
  const stored = asNumber(renter.discountAmount, 0);
  return stored > 0 ? stored : 0;
};

/** Per-booking income component breakdown for reports / CSV. */
export const buildRentalBookingIncomeBreakdown = (booking, slotsV2 = {}, settings = {}) => {
  if (!booking || isOpenPlayCalendarBlock(booking)) {
    return null;
  }

  const { slots, totalDue, amountPaid, balance, paymentStatus: finStatus } =
    getRentalBookingFinancials(booking, slotsV2);

  const renter = booking.renter || {};
  const pickleCamFallback = asNumber(settings.pickleCamFee, 25);
  const ballFallback = asNumber(settings.ballFee, 78);
  const method = String(booking.paymentSummary?.paymentMethod || "").toUpperCase();

  const courtGross = sumRentalSlots(slots);
  const pickleCamPesos = computePickleCamCharge(renter, slots, pickleCamFallback);
  const ballsPesos = computeBallSalesTotal(renter, ballFallback);
  const grossBeforeDiscount = courtGross + pickleCamPesos + ballsPesos;
  const discountPct = asNumber(renter.discount, 0);
  const discountGiven = computeDiscountGiven(renter, grossBeforeDiscount);
  const computedNet = Math.max(0, grossBeforeDiscount - discountGiven);

  let paymentStatus = finStatus;
  if (method === "FREE") paymentStatus = "FREE";

  const netDue = totalDue;
  const adjustment = Math.abs(netDue - computedNet) > 1 ? netDue - computedNet : 0;
  const isFree = paymentStatus === "FREE";

  return {
    bookingId: booking.id,
    courtGross: isFree ? 0 : courtGross,
    pickleCamPesos: isFree ? 0 : pickleCamPesos,
    ballsPesos: isFree ? 0 : ballsPesos,
    discountPct,
    discountGiven: isFree ? 0 : discountGiven,
    grossBeforeDiscount: isFree ? 0 : grossBeforeDiscount,
    computedNet: isFree ? 0 : computedNet,
    adjustment: isFree ? 0 : adjustment,
    netDue: isFree ? 0 : netDue,
    amountPaid: isFree ? 0 : amountPaid,
    balance: isFree ? 0 : balance,
    paymentStatus,
    ballUnits: Math.max(0, Math.floor(asNumber(renter.ballQty, 0))),
    hasPickleCam: !!renter.pickleCam,
  };
};
